************************************************************************
      module NGSDATAMOD
*                                                                      *
*     Nuclear Ground State Data                                        *
*        created by T.Ogawa : 2020/03/12                               *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              setup ground state nuclear data to be shred all         *
*              over PHITS before openmp parallelization                *
*                                                                      *
*                                                                      *
*        Data to be setup:                                             *
*                                                                      *
*           spintbl(0:nnuc)        : ground state spintbl              *
*           be0(0:nnuc)            : ground state binding energy       *
*           parity(0:nnuc)         : ground state parity               *
*           inuc0(0:maxpt,0:maxnt) : pointer table                     *
*                                                                      *
*        Data source:                                                  *
*                                                                      *
*   Site                                                               *
*   https://www-nds.iaea.org/amdc/                                     *
*   Publication                                                        *
*   https://www-nds.iaea.org/amdc/ame2016/NUBASE2016.pdf               *
*   Numerical table                                                    *
*   http://www.oecd-nea.org/dbdata/data/mass-evals2012/nubase.mas12    *
*                                                                      *
************************************************************************
      implicit double precision (a-h,o-z)

      include 'param01.inc'
      parameter (nnuc2 = 9436)
      parameter (nnuc3 = 9107)
      parameter (nnuc4 = 5239)

      common /paran/ icfn(100), ilfn(100), chfn(100) ! phits paths
      character chfn*200
      character FNAme*200

      public :: spin, shellE, energm, bindeg, weitn, gstbl, fisBarr

      integer, private :: nzz0(0:nnuc),  nnn0(0:nnuc),
     &                    nzz2(0:nnuc2), nnn2(0:nnuc2),
     &                    nzz3(0:nnuc3), nna3(0:nnuc3)
      double precision, private :: shellKTUY(0:nnuc2)  ! ground state shell  KTUY
      double precision, private :: shellMySw(0:nnuc3)  ! ground state shell  Myer-Swaitecki
      double precision, private :: FissionBarrier(0:nnuc4)   ! Fission barrier height

      double precision, private :: spintbl(0:nnuc)  ! ground state spintbl
      double precision, private :: be0(0:nnuc)   ! ground state binding energy*
      integer, public           :: parity(0:nnuc)! ground state parity
      ! pointer table
      integer, private          :: inuc0(0:maxpt,0:maxnt),    ! mass spin, parity
     &                             inuc2(0:maxpt,0:maxnt),    ! KTUY Shell correction
     &                             inuc3(0:maxpt,0:maxnt),    ! Myer-Swaitecki Shell correction
     &                             inuc4(0:maxpt,0:maxnt)     ! Fission barrier


