      subroutine gstbl
*                                                                      *
*        Last Revised:     2002/02/15                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              to read ground state table from block data              *
*                                                                      *
*                                                                      *
************************************************************************
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

               inuc0 = 0
               inuc2 = 0
               inuc3 = 0

*-----------------------------------------------------------------------
*           Normal Nucleus data from block data
*-----------------------------------------------------------------------

               do i = 1, nnuc

                  iz = nzz0(i)
                  in = nnn0(i)

                  inuc0(iz,in) = i

               end do


               do i = 1, nnuc2

                  iz = nzz2(i)
                  in = nnn2(i)

                  inuc2(iz,in) = i

               end do

               do i = 1, nnuc3

                  iz = nzz3(i)
                  ia = nna3(i)

                  inuc3(iz,ia-iz) = i

               end do

*-----------------------------------------------------------------------

      return
      end subroutine



*********  Read from external file *************************************

************************************************************************
*                                                                      *
      subroutine fstbl(ierr)
*                                                                      *
*        Last Revised:     2002/05/19                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              to read fission barrier table from block data           *
*                                                                      *
*                                                                      *
************************************************************************
      implicit double precision (a-h,o-z)
      include 'err.inc'

*-----------------------------------------------------------------------

      inuc4          = 0
      FissionBarrier = 0.d0

*-----------------------------------------------------------------------
*           Normal Nucleus data from block data
*-----------------------------------------------------------------------
      FNAme = chfn(1)(1:ilfn(1))//'/data/'//
     &'Fission_barrier_table_PhysRevC_91_024310.dat'

      OPEN(302, FILE = FNAme, STATUS = 'old',ERR=201)

      i = 0

      do
        i = i + 1

        READ(302, *, END = 200)iz, in, ia, bar

        FissionBarrier(i) = bar

        if(iz .gt. 130 .or. in .gt. 230) then
         write(*,*) 'fission barrier data charge or mass is too large',
     &    iz, in
         write(*,*) 'Expand inuc4 array'
         stop
        endif

        inuc4(iz,in) = i

      end do

 200  CLOSE(302)
      return
*-----------------------------------------------------------------------

 201  write(*,*) '!!!!!! Please check file(1) parameter or',
     &' update data folder !!!!!!'
      write(*,*) 'Fission_barrier_table_PhysRevC_91_024310.dat is
     & missing in data folder'
      ErrCha = ''
      ErrID = 'L:10161/R:fstbl/F:ngsdatamod.f'
      call ErrWrite(ErrID,ErrCha)
      ierr = -1
      return
      end subroutine


*********  Functions to call data **************************************

************************************************************************
*                                                                      *
      function fisBarr(iz, ia, inout)
*                                                                      *
*        Last Revised:     2020/05/19                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*            call and return fission barrier from data if available    *
*                                                                      *
*     input  :                                                         *
*       iz     : mass number                                           *
*       ia     : atomic number                                         *
*       inout  : inner=(1) / outer=(2) barrier identification          *
*                                                                      *
*                                                                      *
*     output :                                                         *
*      fisBarr : fission barrier height  [MeV]                         *
*                                                                      *
*      Data source :                                                   *
*       Peter Moller, Arnold J. Sierk, Takatoshi Ichikawa,             *
*                            Akira Iwamoto, Matthew Mumpower,          *
*                         PHYSICAL REVIEW C 91, 024310 (2015)          *
************************************************************************
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------
! Currently, inner barrier and outer barriers are the same

      fisBarr = FissionBarrier(inuc4(iz,ia-iz))

*-----------------------------------------------------------------------
      return
      end function

*-----------------------------------------------------------------------

************************************************************************
*                                                                      *
      function weitn(nz,nn)
*                                                                      *
*                                                                      *
*        Last Revised:     2002 02 15                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              to give weight (1.e-24 g)                               *
*              Experimental Data                                       *
*                                                                      *
*        Variables:                                                    *
*                                                                      *
*              nz          : proton  number                            *
*              nn          : neutron number                            *
*                                                                      *
************************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      data rpms / 938.27d0 /
      data rnms / 939.58d0 /

*-----------------------------------------------------------------------
      weitn = nz * rpms + nn * rnms - bindeg(nz,nn)

      weitn = weitn * 1.78266270d-3

*-----------------------------------------------------------------------

      return
      end function


************************************************************************
*                                                                      *
      function bindeg(nz,nn)
*                                                                      *
*                                                                      *
*        Last Revised:     2002 02 15                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              to give binding energy (MeV)                            *
*              Experimental Data                                       *
*                                                                      *
*        Variables:                                                    *
*                                                                      *
*              nz          : proton  number                            *
*              nn          : neutron number                            *
*                                                                      *
************************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      parameter( bvol=15.56d0, bsur=17.23d0, bsym=46.57d0, coul=1.2d0 )

*-----------------------------------------------------------------------

               if ( nn .gt. 400 ) nn = nn - 400 ! S.H. for meta-stable

               bindeg = 0.0

               mm = nz + nn

*-----------------------------------------------------------------------
*        check
*-----------------------------------------------------------------------

            if( nz .lt. 0 .or. nn .lt. 0 .or.
     &          mm .le. 1 ) then

               return

*-----------------------------------------------------------------------
*        Normal Nucleus
*-----------------------------------------------------------------------

            else if( nz .le. maxpt .and. nn .le. maxnt .and.
     &               inuc0(nz,nn) .ne. 0 ) then

               bindeg = be0( inuc0(nz,nn) )

*-----------------------------------------------------------------------
*        Super Heavy Nuclei or out of table
*        Use Liquid Drop Mass Formula
*-----------------------------------------------------------------------

            else

               a  = dble( mm )
               rc = 1.24d0 * a**(1.0d0/3.0d0)

               bindeg = ( bvol * a
     &                - bsur * a**(2.0d0/3.0d0)
     &                - bsym / 2.0d0 * ( nn - nz ) * ( nn - nz ) / a
     &                - 3.0d0/5.0d0 * nz * coul * nz * coul / rc )

            end if

*-----------------------------------------------------------------------

      return
      end function

************************************************************************
*                                                                      *
      function energm(iz,ia,nv)
*
*  ENERGY
*    Calculate excess mass
*=====================================================================
* <variables>
*     ia   :   mass of nucleus                      (IN)
*     iz   :   charge  of nucleus                   (IN)
*     nv   :   version number                       (IN)
*        1-> Old algorithm
*        2-> RIPL data
*  energm  :   Excess mass [MeV]                   (OUT)
************************************************************************
      implicit doubleprecision(a-h,o-z)

      include 'param-physcnst.inc'

      logical isz, isn
      parameter (inn=150, izz=98)
      common /cook/ sz(izz), sn(inn), con(2), amean(240), pz(izz),
     1 pn(inn), isz(izz), isn(inn)
!$OMP THREADPRIVATE(/cook/)

      data afact, zfact, enmass /8.071323d0,0.782354d0,939.56563d0/


      if(nv .eq. 2) then
         energm = dble(iz) * rstms(1) * 1.d3
     &          + dble(ia -iz) * rstms(2) * 1.d3
     &          - bindeg(iz,ia-iz) - dble(ia) * rstms(0) * 1.d3
         if(energm.le.0.d0) goto 10

      elseif(nv .eq. 1) then

         energm=1.d10

         if(iz.eq.0.and.ia.gt.10) then
            energm=15.d0*ia
            return
         end if

         in=ia-iz
         if (iz.ge.0.and.iz.le.150.and.ia-iz.ge.0.and.ia-iz.le.250) then
         energm = dble(iz) * rstms(1) * 1.d3
     &          + dble(ia -iz) * rstms(2) * 1.d3
     &          - bindeg(iz,ia-iz) - dble(ia) * rstms(0) * 1.d3
            if(energm.eq.0.d0) goto 10
            return
         endif
      else
       write(*,*) 'excess mass calculator version is neither 1 nor 2',nv
       return
      endif

Cameron's mass formula
 10   if(iz.eq.6.and.ia.eq.12) return

      if( iz .eq. 0 .or. ia-iz .eq. 0) return

      n=ia-iz
      a=dble(ia)
      z=dble(iz)

      a3=exp(0.3333333333d0*log(a))

      izk = min(iz,izz)
      ink = min(n,inn)
      cam=8.071323d0*a-0.782354d0*z-17.0354d0*a*(1.d0-1.84619d0
     1 *(a-2.d0*z)**2/a**2)+25.8357d0*a3**2*(1.d0-1.71219d0*(a-2.d0*z)
     2 **2/a**2)*(1.d0-0.62025d0/a3**2)**2+0.779d0*z*(z-1.d0)*(1.d0-1.5
     3 849d0/a3**2+1.2273d0/a+1.5772d0/(a*a3))/a3-0.4323d0*exp(1.3333333
     4 333d0*log(z))*(1.d0-0.57811d0/a3-0.14518d0/a3**2+0.49597d0/a)/a3

      energm=cam + sz(izk) + sn(ink)

      return
      end function

************************************************************************
*                                                                      *
      function shellE(iz, ia, nv)
*                                                                      *
*        Last Revised:     2020/03/31                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*            call and return ground state shell energy from data if    *
*            available                                                 *
*                                                                      *
*     input  :                                                         *
*       iz     : mass number                                           *
*       ia     : atomic numbe r                                        *
*       nv     : Data version.  1:KTUY  2:Myers-Swiatecki              *
*                                                                      *
*    1: H. Koura, T. Tachibana, M. Uno and M. Yamada,                  *
*                              Prog. Theor. Phys. 113 (2005) 305.      *
*    2: W.D. Myers and W.J. Swiatecki, Ark. Fizik. 36, 343 (1967).     *
*                                                                      *
*                                                                      *
*     output :                                                         *
*       shellE : shell energy       [MeV]                              *
************************************************************************
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      if(nv .eq. 1) then
          shellE = shellKTUY(inuc2(iz,ia-iz))
      elseif(nv .eq. 2) then
          shellE = shellMySw(inuc3(iz,ia-iz))
      endif

*-----------------------------------------------------------------------
      return
      end function

*-----------------------------------------------------------------------

************************************************************************
*                                                                      *
      function spin(ityp, kf)
*                                                                      *
*        Last Revised:     2020/03/13                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*            call and return ground state spin from data if available  *
*            and return 0 or 1/2 if not                                *
*                                                                      *
************************************************************************
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      select case(ityp)
       case(1:2,6:7,11:13,16:17)
        spin = 0.5d0
       case(3:5,8:10,14,18)
        spin = 0.d0
       case(15)
        spin = 1.d0
       case(19)
        iz = kf/1000000
        in = kf-iz*1000001
        if(inuc0(iz,in) .ne. 0) then
         spin = spintbl(inuc0(iz,in))
        elseif(mod(iz+in,2) .eq. 0) then
         spin = 0.d0
        else
         spin = 0.5d0
        endif
      end select

*-----------------------------------------------------------------------
      return
      end function


************************************************************************
*                                                                      *
      function ngsdcy(nz,na)
*                                                                      *
*                                                                      *
*        Last Revised:     2020 04 02                                  *
*                                                                      *
*        Purpose:                                                      *
*                                                                      *
*              Define ground state decay path                          *
*                                                                      *
*        Input:                                                        *
*                                                                      *
*              nz          : proton  number of parent                  *
*              nn          : neutron number or parent                  *
*                                                                      *
*       Output:                                                        *
*                                                                      *
*              ngsdcy      :      1 neutron                            *
*            (1000*z+a)    :   1001 proton                             *
*                                                                      *
************************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      ngsdcy = 0

      SelectCase(nz)

        Case(1)
          SelectCase(na)
          Case(4:)
             ngsdcy = 1
          End select

        Case(2)
          SelectCase(na)
          Case(5,7,9)
             ngsdcy = 1
          End select

        Case(3)
          SelectCase(na)
          Case(10)
             ngsdcy = 1
          Case(:5)
             ngsdcy = 1001
          End select

        Case(4)
          SelectCase(na)
          Case(13)
             ngsdcy = 1
          Case(8)
             ngsdcy = 2004
          Case(:6)
             ngsdcy = 1001
          End select

        Case(5)
          SelectCase(na)
          Case(16)
             ngsdcy = 1
          Case(:7,9)
             ngsdcy = 1001
          End select

      end select

*-----------------------------------------------------------------------

      return
      end function



*-----------------------------------------------------------------------
      end module NGSDATAMOD
